import math
_prev = [None, 0.0]

def control(obs):
    h = float(obs.get('hitch_deg', 0.0) or 0.0)
    st = obs.get('status', 'READY')
    t = float(obs.get('t', 0.0) or 0.0)
    dh = 0.0
    if _prev[0] is not None:
        dt = t - _prev[0]
        if dt > 1e-6:
            dh = (h - _prev[1]) / dt
    _prev[0] = t
    _prev[1] = h
    if st in ('JACKKNIFED', 'PINNED'):
        return {'steer_deg': 0.0, 'speed_mps': 1.0, 'look_deg': -23}
    steer = 2.0 * h + 0.8 * dh
    steer = max(-30.0, min(30.0, steer))
    return {'steer_deg': steer, 'speed_mps': -1.0, 'look_deg': -23}

