_st = {'phase': 'fwd', 't0': None, 'prev': None}

def control(obs):
    t = float(obs.get('t', 0.0) or 0.0)
    h = float(obs.get('hitch_deg', 0.0) or 0.0)
    st = obs.get('status', 'READY')
    if _st['t0'] is None:
        _st['t0'] = t
    dh = 0.0
    if _st['prev'] is not None:
        pt, ph = _st['prev']
        if t - pt > 1e-6:
            dh = (h - ph) / (t - pt)
    _st['prev'] = (t, h)
    if st == 'JACKKNIFED' and _st['phase'] == 'rev':
        _st['phase'] = 'fwd'
        _st['t0'] = t
    if _st['phase'] == 'fwd':
        if t - _st['t0'] < 2.5:
            return {'steer_deg': -12.0, 'speed_mps': 1.0, 'look_deg': -23}
        _st['phase'] = 'rev'
        _st['t0'] = t
    target = -2.0 if t - _st['t0'] < 6.0 else 0.0
    steer = 2.0 * (h - target) + 0.8 * dh
    steer = max(-30.0, min(30.0, steer))
    return {'steer_deg': steer, 'speed_mps': -1.0, 'look_deg': -23}

