def control(obs):
    t=float(obs.get('t',0.0) or 0.0)
    h=float(obs.get('hitch_deg',0.0) or 0.0)
    st=obs.get('status','READY')
    if st in ('JACKKNIFED','PINNED'):
        _s['prev']=None
        return {'steer_deg':0.0,'speed_mps':0.5,'look_deg':-23}
    rig=obs.get('rig') or {}
    tr=rig.get('trailer_rear') or [0.0,0.0]
    ry=float(tr[1])
    dh=0.0
    if _s['prev'] is not None:
        pt,ph=_s['prev']
        if t-pt>1e-6:
            dh=(h-ph)/(t-pt)
    _s['prev']=(t,h)
    tgt=-3.0 if ry>-0.2 else 0.0
    steer=2.5*(h-tgt)+0.8*dh
    steer=max(-30.0,min(30.0,steer))
    return {'steer_deg':steer,'speed_mps':-0.4,'look_deg':-23}

