RY_T = -0.25

def control(obs):
    global PH, PT
    h = obs['hitch_deg']
    ry = obs['rig']['trailer_rear'][1]
    st = obs['status']
    dt = obs['dt']
    if PH == 'REV' and (abs(h) > 60 or st == 'JACKKNIFED'):
        PH = 'PULL'
        PT = 0.0
    if PH == 'PULL':
        PT += dt
        if (abs(h) < 2.5 and PT > 1.0) or PT > 6.0:
            PH = 'REV'
        else:
            return (0.0, 0.4, 180)
    steer = 1.8 * h + 10.0 * (ry - RY_T)
    steer = max(-40.0, min(40.0, steer))
    return (steer, -0.5, 180)

