def control(obs):
    h = obs.get('hitch_deg', 0.0)
    mx = obs.get('max_hitch_deg', 0.0)
    st = obs.get('status', 'READY')
    if st == 'JACKKNIFED' or abs(h) > 70:
        return (0.0, 0.0)
    # hitch-following: positive steer drives hitch down while reversing
    steer = 1.6 * h
    # small right-bias (negative steer) to keep the trailer rear right of centre
    steer -= 2.0
    if steer > 42: steer = 42.0
    if steer < -42: steer = -42.0
    speed = -1.0
    if abs(h) > 35:
        speed = -0.5
    return (steer, speed)

